contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint initialAmount, uint callAmount) public payable {
        require(initialAmount <= address(this).balance, "insufficient balance for setup");
        require(callAmount <= address(this).balance - initialAmount, "insufficient balance for call");

        // Optional setup: a first fallback call may be made with exactly 10 ether to establish
        // a non-zero pastBlockTime. This call succeeds if and only if block.timestamp > 0,
        // which is always true.
        if (initialAmount == 10 ether) {
            (bool setupOk, ) = address(c).call{value: initialAmount}("");
            require(setupOk, "setup call failed");
        }

        uint beforeTime = c.pastBlockTime();

        bool reverted;
        (bool callOk, ) = address(c).call{value: callAmount}("");
        reverted = !callOk;

        // General rule: the fallback reverts exactly when the amount is not 10 ether,
        // or when the timestamp is not strictly greater than the pre-call pastBlockTime.
        assert(reverted == (callAmount != 10 ether || beforeTime >= block.timestamp));
    }
}

