contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 firstValue, uint256 secondValue) public payable {
        require(address(this).balance >= firstValue + secondValue);

        // First call: with arbitrary value, possibly with correct amount. Its purpose is to
        // set a public pastBlockTime and observe the threshold. We do this via a top-level call.
        bool firstReverted;
        try c.fallback{value: firstValue}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 beforeTime = c.pastBlockTime();

        // Second call: exactly 10 ether, the required amount. Its outcome should be governed
        // solely by whether the current block.timestamp is strictly greater than beforeTime.
        bool secondReverted;
        try c.fallback{value: secondValue}() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 afterTime = c.pastBlockTime();

        // If the second call completed, the guard was satisfied and the timestamp was recorded.
        // If it reverted, the guard was not satisfied (or the amount was not exactly 10 ether).
        // Since the value is a parameter, the rule must account for the exact-10-ether requirement.
        if (secondValue == 10 ether) {
            assert(
                secondReverted == (block.timestamp <= beforeTime)
            );
            if (!secondReverted) {
                assert(afterTime > beforeTime);
            }
        }
    }
}

