contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 targetTimestamp) public payable {
        require(address(this).balance >= amount);

        // Snapshot before-state through public surface
        uint256 before = c.pastBlockTime();

        // Ensure the call's block.timestamp is strictly greater than current pastBlockTime
        require(block.timestamp > before);
        uint256 desired = block.timestamp;

        bool reverted;
        if (amount == 10 ether) {
            // Call that changes state, top-level statement
            (bool ok, ) = address(c).call{value: amount}("");
            reverted = !ok;
            if (!reverted) {
                // Read after-state through public getter
                uint256 afterTs = c.pastBlockTime();
                assert(afterTs == desired);
            } else {
                // If it reverted, pastBlockTime must be unchanged
                uint256 afterTs = c.pastBlockTime();
                assert(afterTs == before);
            }
        } else {
            // amount != 10 ether: call must revert, state unchanged
            (bool ok, ) = address(c).call{value: amount}("");
            reverted = !ok;
            uint256 afterTs = c.pastBlockTime();
            assert(reverted == true && afterTs == before);
        }
    }

    receive() external payable {}
}

