contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint64 ts) public payable {
        require(address(this).balance >= 10 ether);
        require(ts > block.timestamp);
        uint256 beforeTime = c.pastBlockTime();
        bool reverted;
        // cannot set block.timestamp directly; instead compare against current timestamp,
        // but the rule must be general over ts. To test the fallback, we need a timestamp
        // condition. Since we can't change block.timestamp, we use the only available path:
        // call fallback and observe revert/success. The rule is about what the contract does
        // for any timestamp. The assertion must hold for all inputs, so we assert the
        // logical equivalence using the current block.timestamp as the actual timestamp used.
        try c.call{value: 10 ether}("") {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTime = c.pastBlockTime();
        // After the call, the contract's logic guarantees:
        //   reverted == (block.timestamp <= beforeTime)
        // and if not reverted, afterTime == block.timestamp.
        // We cannot change block.timestamp, so the test runs with the current timestamp.
        // The rule is: if the call succeeded, then block.timestamp > beforeTime and afterTime == block.timestamp;
        // if it reverted, then block.timestamp <= beforeTime.
        assert(reverted ? (block.timestamp <= beforeTime) : (block.timestamp > beforeTime && afterTime == block.timestamp));
    }

    receive() external payable {}
}

