contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint64 ts) public payable {
        // amount must cover exactly 10 ether; ts is the block timestamp we simulate via state setup.
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        bool shouldSucceed = ts > c.pastBlockTime();

        if (shouldSucceed) {
            // Advance c's pastBlockTime to ts via a successful fallback call.
            // This requires block.timestamp > c.pastBlockTime() to hold naturally.
            // If the ambient block.timestamp does not allow it, skip the positive branch.
            if (block.timestamp > c.pastBlockTime()) {
                (bool ok1, ) = address(c).call{value: amount}("");
                require(ok1);
            }
        }

        uint before = c.pastBlockTime();

        bool reverted;
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        uint after = c.pastBlockTime();

        // General rule: the call succeeds iff it was sent exactly 10 ether and the
        // current block timestamp is strictly greater than the previously stored pastBlockTime.
        // On success, pastBlockTime is updated to block.timestamp; on failure it is unchanged.
        if (reverted) {
            assert(after == before);
        } else {
            assert(after == block.timestamp);
        }
    }

    receive() external payable {}
}

