        require(block.timestamp > c.pastBlockTime());

        require(address(this).balance >= 10 ether);

        // Make the timestamp strictly advance past the stored one.
        uint target = c.pastBlockTime() + advance;
        if (block.timestamp <= target) {
            block.timestamp = target;
        }

        bool shouldSucceed = amount == 10 ether;
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterTime = c.pastBlockTime();

        // Rule: a direct call with exactly 10 ether must succeed and set pastBlockTime
        // to the current timestamp; otherwise it must revert with pastBlockTime unchanged.
        assert(reverted == !shouldSucceed && (shouldSucceed ? afterTime == block.timestamp : afterTime == c.pastBlockTime()));
        assert(!shouldSucceed || afterBalance >= 10 ether);
    }

    receive() external payable {}
}

