contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint wait) public payable {
        require(address(this).balance >= amount);
        require(wait <= 1000000);

        // Ensure a prior successful call with value 10 ether to set pastBlockTime.
        // amount must be at least 10 ether for this setup to succeed.
        require(amount >= 10 ether);

        // Push block.timestamp far enough forward for the setup call.
        // (The checker runs this in a single transaction; the actual timestamp
        //  may not change, so we use a conservative approach: if the setup
        //  reverts due to timestamp <= pastBlockTime, we still test the rule
        //  on a state where pastBlockTime is whatever it is.)
        uint setupVal = 10 ether;
        require(address(this).balance >= setupVal);

        uint beforeTime = c.pastBlockTime();

        bool setupOk = true;
        try c.fallback{value: setupVal}() {
        } catch {
            setupOk = false;
        }

        uint afterTime = c.pastBlockTime();

        // Now perform the deciding call with the provided amount.
        uint pastBeforeDecide = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pastAfterDecide = c.pastBlockTime();

        // General rule: fallback reverts iff (msg.value != 10 ether) OR
        // (block.timestamp <= pastBlockTime at call time).
        // Since we can't read block.timestamp at the exact call time after
        // the call, we express the rule using observable state changes:
        //   - If the call succeeds, pastBlockTime becomes a strictly larger
        //     value than it was before (timestamp monotonicity).
        //   - If the call succeeds, pastAfterDecide > pastBeforeDecide.
        //   - If the call reverts, then either the value was not 10 ether
        //     or the timestamp was not strictly greater; in the latter case
        //     pastBlockTime remains unchanged.
        // The key non-trivial observable: a successful call ALWAYS updates
        // pastBlockTime to a strictly greater value.
        // And: if the call succeeds, amount must be exactly 10 ether.

        bool valueOk = (amount == 10 ether);

        // Main assertion: success implies valueOk and timestamp strictly increased.
        // Failure (revert) is possible when !valueOk, or when timestamp condition fails.
        assert(
            reverted == (!valueOk || pastAfterDecide == pastBeforeDecide) ||
            (!reverted && valueOk && pastAfterDecide > pastBeforeDecide)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
