        // Setup: make one successful call if possible, to establish a nonzero pastBlockTime.
        // Send exactly 10 ether, which is the only accepted amount; this succeeds if
        // the timestamp condition is met.
        uint setupVal = 10 ether;
        if (address(this).balance >= setupVal) {
            // cannot use try/catch with fallback directly; call via low-level and ignore failure
            (bool setupOk, ) = address(c).call{value: setupVal}("");
            setupOk; // silence unused warning
        }

        uint pastBefore = c.pastBlockTime();

