        }

        uint pastAfter = c.pastBlockTime();

        // The rule: success implies amount == 10 ether and pastAfter > pastBefore.
        // Revert implies either amount != 10 ether or pastAfter == pastBefore.
        assert(
            (reverted && (amount != 10 ether || pastAfter == pastBefore)) ||
            (!reverted && amount == 10 ether && pastAfter > pastBefore)
        );
    }

